mapper.select:
SELECT t.id, t.ticket_no, t.title, t.description, t.category_id, t.priority, t.status,
       t.creator_id, t.assignee_id, t.team_id, t.due_time, t.completed_time, t.closed_time,
       t.overdue, t.tags, t.create_time, t.update_time, t.create_by, t.update_by, t.deleted
FROM ticket t
WHERE t.deleted = 0
  AND (
    #{admin} = TRUE
    OR t.creator_id = #{currentUserId}
    OR t.assignee_id = #{currentUserId}
    OR EXISTS (
      SELECT 1
      FROM team_member tm
      WHERE tm.team_id = t.team_id
        AND tm.user_id = #{currentUserId}
        AND tm.deleted = 0
    )
  )

  AND t.creator_id = #{currentUserId}


  AND t.assignee_id = #{currentUserId}


  AND EXISTS (
    SELECT 1
    FROM ticket_watch tw
    WHERE tw.ticket_id = t.id
      AND tw.user_id = #{currentUserId}
      AND tw.deleted = 0
  )


  AND t.ticket_no LIKE CONCAT('%', #{ticketNo}, '%')


  AND (t.title LIKE CONCAT('%', #{keyword}, '%')
       OR t.description LIKE CONCAT('%', #{keyword}, '%'))


  AND t.status = #{status}


  AND t.priority = #{priority}


  AND t.category_id = #{categoryId}


  AND t.creator_id = #{creatorId}


  AND t.assignee_id = #{assigneeId}


  AND t.team_id = #{teamId}


  AND t.overdue = #{overdue}


  AND t.create_time >= #{createdFrom}


  AND t.create_time <= #{createdTo}

ORDER BY t.create_time DESC, t.id DESC
